// Accept implementation for escapeChar - an escape sequence
//
// escapeChar  (an escape sequence)
// = "\\\\"                                     -- backslash
// | "\\\""                                     -- doubleQuote
// | "\\\'"                                     -- singleQuote
// | "\\b"                                      -- backspace
// | "\\n"                                      -- lineFeed
// | "\\r"                                      -- carriageReturn
// | "\\t"                                      -- tab
// | "\\u{" hexDigit hexDigit? hexDigit?
// hexDigit? hexDigit? hexDigit? "}"   -- unicodeCodePoint
// | "\\u" hexDigit hexDigit hexDigit hexDigit  -- unicodeEscape
// | "\\x" hexDigit hexDigit                    -- hexEscape
func (node *LexEscapeChar[P, R]) Accept(this goohm.Node, visitor any, payload P) (result R, err error) {
	goohm.AssertName(this, "escapeChar")
	if v, ok := visitor.(Switcher_LexEscapeChar[P, R]); ok {
		v.SwitchLexEscapeChar(node)
		return
	}
	if v, ok := visitor.(SwitcherE_LexEscapeChar[P, R]); ok {
		err = v.SwitchLexEscapeChar(node)
		return
	}
	if v, ok := visitor.(SwitcherP_LexEscapeChar[P, R]); ok {
		v.SwitchLexEscapeChar(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherPE_LexEscapeChar[P, R]); ok {
		err = v.SwitchLexEscapeChar(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherR_LexEscapeChar[P, R]); ok {
		result = v.SwitchLexEscapeChar(node)
		return
	}
	if v, ok := visitor.(SwitcherRE_LexEscapeChar[P, R]); ok {
		result, err = v.SwitchLexEscapeChar(node)
		return
	}
	if v, ok := visitor.(SwitcherPR_LexEscapeChar[P, R]); ok {
		result = v.SwitchLexEscapeChar(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherPRE_LexEscapeChar[P, R]); ok {
		result, err = v.SwitchLexEscapeChar(node, payload)
		return
	}
	goohm.TypeCheckMethod[P, R](visitor, "LexEscapeChar")
	return node.DefaultAccept(visitor, payload)
}

func (node *LexEscapeChar[P, R]) DefaultAccept(visitor any, payload P) (result R, err error) {
	switch node.Node.CtorName() {
	case "LexEscapeChar":
		return (&LexEscapeChar[P, R]{
			Node: node.Node.Children()[0].(goohm.RuleNode),
		}).DefaultAccept(visitor, payload)
	case "escapeChar_backslash":
		kids := node.Node.Children()
		return (&LexEscapeCharBackslash[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_doubleQuote":
		kids := node.Node.Children()
		return (&LexEscapeCharDoubleQuote[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_singleQuote":
		kids := node.Node.Children()
		return (&LexEscapeCharSingleQuote[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_backspace":
		kids := node.Node.Children()
		return (&LexEscapeCharBackspace[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_lineFeed":
		kids := node.Node.Children()
		return (&LexEscapeCharLineFeed[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_carriageReturn":
		kids := node.Node.Children()
		return (&LexEscapeCharCarriageReturn[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_tab":
		kids := node.Node.Children()
		return (&LexEscapeCharTab[P, R]{
			Term: kids[0].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_unicodeCodePoint":
		kids := node.Node.Children()
		return (&LexEscapeCharUnicodeCodePoint[P, R]{
			Term1:     kids[0].(goohm.TerminalNode),
			HexDigit1: kids[1].(goohm.RuleNode),
			HexDigit2: kids[2].(goohm.OptNode),
			HexDigit3: kids[3].(goohm.OptNode),
			HexDigit4: kids[4].(goohm.OptNode),
			HexDigit5: kids[5].(goohm.OptNode),
			HexDigit6: kids[6].(goohm.OptNode),
			Term2:     kids[7].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_unicodeEscape":
		kids := node.Node.Children()
		return (&LexEscapeCharUnicodeEscape[P, R]{
			Term:      kids[0].(goohm.TerminalNode),
			HexDigit1: kids[1].(goohm.RuleNode),
			HexDigit2: kids[2].(goohm.RuleNode),
			HexDigit3: kids[3].(goohm.RuleNode),
			HexDigit4: kids[4].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "escapeChar_hexEscape":
		kids := node.Node.Children()
		return (&LexEscapeCharHexEscape[P, R]{
			Term:      kids[0].(goohm.TerminalNode),
			HexDigit1: kids[1].(goohm.RuleNode),
			HexDigit2: kids[2].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	default:
		panic("unexpected " + node.Node.CtorName())
	} // end switch
}

